interface Pending<T> { resolve(v: T): void; reject(e: Error): void; timer: NodeJS.Timeout; }
const pending = new Map<string, Pending<unknown>>();

function call<T>(payload: unknown, timeoutMs = 5_000): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const id = randomUUID();
    const timer = setTimeout(() => { pending.delete(id); reject(new Error(`no reply for ${id}`)); }, timeoutMs);
    pending.set(id, { resolve: resolve as (v: unknown) => void, reject, timer });  // register BEFORE send
    socket.send(JSON.stringify({ id, payload }));
  });
}

socket.on("message", (raw) => {
  const msg = JSON.parse(raw) as { id: string; payload: unknown };
  const d = pending.get(msg.id);
  if (!d) return;                                   // unknown or late id: drop
  pending.delete(msg.id); clearTimeout(d.timer); d.resolve(msg.payload);
});
